  "pf.rent_per_sqm_note": { "zh-CN": "月租按全租期固定租金直线化计算，因此免租期与递增条款不影响可比性；单价仅统计已填写租赁面积的合同。", "zh-HK": "月租按全租期固定租金直線化計算，因此免租期與遞增條款不影響可比性；單價僅統計已填寫租賃面積的合同。", en: "Monthly rent is straight-lined across the full term, so rent-free periods and escalations do not distort comparability; the unit price counts only contracts with a recorded area." },
  "pf.no_area_data": { "zh-CN": "暂无可比数据：请先为合同填写租赁面积", "zh-HK": "暫無可比數據：請先為合同填寫租賃面積", en: "Nothing to compare yet — record a leased area on the contracts first" },
  "pf.missing_area_warning": { "zh-CN": "有 {count} 份合同未填写租赁面积，未纳入单价计算", "zh-HK": "有 {count} 份合同未填寫租賃面積，未納入單價計算", en: "{count} contracts have no leased area and are excluded from the unit price" },
  "pf.missing_area_desc": { "zh-CN": "补齐合同的租赁面积后，单价与对比结果才覆盖完整组合。", "zh-HK": "補齊合同的租賃面積後，單價與對比結果才覆蓋完整組合。", en: "Fill in the leased area to make the unit price cover the whole portfolio." },
