  "plan_import.hint_plain": { "zh-CN": "请按模板填写门店与期间的经营计划数据；单行出错不影响其余行入库。", "zh-HK": "請按模板填寫門店與期間的經營計劃數據；單行出錯不影響其餘行入庫。", en: "Fill the template with store and period plan figures; a bad row never blocks the rest." },
  "tb_import.hint_plain": { "zh-CN": "请按模板填写科目余额；同一来源与期间重复导入不会重复入账。", "zh-HK": "請按模板填寫科目餘額；同一來源與期間重複導入不會重複入賬。", en: "Fill the template with account balances; re-importing the same source and period will not double-post." },
  "plan_import.hint": { "zh-CN": "标准模板包含门店代码、期间(YYYY-MM)、币种、营收、毛利、人工、固定租金、变动租金、非租成本与经营利润；行级校验隔离，格式异常不影响其余行入库", "zh-HK": "標準模板包含門店代碼、期間(YYYY-MM)、幣種、營收、毛利、人工、固定租金、變動租金、非租成本與經營利潤；行級校驗隔離，格式異常不影響其餘行入庫", en: "Standard template columns: store_code, period (YYYY-MM), currency, revenue, gross_profit, labor_cost, fixed_rent, variable_rent, non_lease_cost, four_wall_ebitda; row-level isolation ensures clean rows ingest safely" },
