  "tb_import.title": { "zh-CN": "GL 试算平衡表导入", "zh-HK": "GL 試算平衡表導入", en: "GL trial balance import" },
  "tb_import.hint": { "zh-CN": "受控模板列：科目代码、科目名称（可选）、借方金额、贷方金额；同一来源与期间重复导入将自动拦截重复提交；功能货币为对账基础", "zh-HK": "受控模板列：科目代碼、科目名稱（可選）、借方金額、貸方金額；同一來源與期間重複導入將自動攔截重複提交；功能貨幣為對賬基礎", en: "Template columns: account_code, account_name (optional), debit, credit; duplicate imports replay idempotently; functional currency is the reconciliation basis" },
