  "fpna.rolling_forecast_notice_desc": { "zh-CN": "系统严格遵守单 Draft 预测不变量与混合替换纪律：截止期（Cutoff）前的期间自动由已关账的实际数替换，未来期间保留基准预测。编制完成后将生成带完整血缘关系的独立 Forecast 版本。", "zh-HK": "系統嚴格遵守單 Draft 預測不變量與混合替換紀律：截止期（Cutoff）前的期間自動由已關賬的實際數替換，未來期間保留基準預測。編制完成後將生成帶完整血緣關係的獨立 Forecast 版本。", en: "Enforces single draft forecast invariant and hybrid composition rules: past periods through cutoff are replaced by actuals, future periods retain baseline forecast, creating an auditable forecast version." },
