  "pre_deal.label_exit_penalty": { "zh-CN": "提前退出罚金（月租金）", "zh-HK": "提前退出罰金（月租金）", en: "Early-exit penalty (months of rent)" },
  "pre_deal.hint_exit_penalty": { "zh-CN": "按退出时点在租的租金计", "zh-HK": "按退出時點在租的租金計", en: "Based on rent in force at exit" },
