  "fpna.operating_scope_desc": { "zh-CN": "本工作台面向 FP&A 与财务 BP，维护营收、毛利、人工、固定与变量租金及门店四面墙 EBITDA（经营占用口径）。若需查看法定使用权资产折旧、利息与付款的租赁会计预算，请前往", "zh-HK": "本工作台面向 FP&A 與財務 BP，維護營收、毛利、人工、固定與變量租金及門店四面牆 EBITDA（經營佔用口徑）。若需查看法定使用權資產折舊、利息與付款的租賃會計預算，請前往", en: "This workbench serves FP&A and Finance BP for operating P&L and 4-wall EBITDA. For statutory lease accounting IFRS 16 interest, depreciation, and payments, go to" },
  "fpna.lease_budget_name": { "zh-CN": "租赁预算差异（IFRS 16 口径）", "zh-HK": "租賃預算差異（IFRS 16 口徑）", en: "Lease Budget Variance (IFRS 16 Basis)" },
