  "cashflow.scenario.intro": { "zh-CN": "按到期日排的租金流水是一张日程表，它假设每份租约都在到期日停止。下面按比例假设「续掉多少、关掉多少」，并始终与不做假设的基准并排显示。", "zh-HK": "按到期日排的租金流水是一張日程表，它假設每份租約都在到期日停止。下面按比例假設「續掉多少、關掉多少」，並始終與不做假設的基準並排顯示。", en: "Scheduled cashflow by expiry assumes every lease terminates exactly on date. Below simulates renewal and closure rates side-by-side against the baseline." },
